effect.shader:

precision highp float;
in vec2 fragCoord;
out vec4 fragColor;
uniform sampler2D uTexture;
uniform float exposure;
uniform float contrast;
uniform float saturation;
uniform float halation;
uniform float diffusion;
uniform float temperature;

void main() {
    vec4 col = texture(uTexture, fragCoord);

    // Exposure & Contrast
    col.rgb *= pow(2.0, exposure);
    col.rgb = (col.rgb - 0.5) * contrast + 0.5;

    // Saturation
    float luma = dot(col.rgb, vec3(0.299, 0.587, 0.114));
    col.rgb = mix(vec3(luma), col.rgb, saturation);

    // Cinematic Halation (Red/Orange glow on highlights)
    float highlight = max(col.r, max(col.g, col.b));
    if (highlight > 0.7) {
        col.rgb += vec3(halation * 0.3, halation * 0.1, 0.0);
    }

    // Color Temperature adjustment
    float tempFactor = (temperature - 5500.0) / 6500.0;
    col.r += tempFactor * 0.1;
    col.b -= tempFactor * 0.1;

    fragColor = clamp(col, 0.0, 1.0);
}
